// StatusString returns a mnemonic for the documented status codes, otherwise the
// hex value.
func StatusString(status uint32) string {
	switch status {
	case StatusSuccess:
		return "ERROR_SUCCESS"
	case ErrorAccessDenied:
		return "ERROR_ACCESS_DENIED"
	case ErrorNotEnoughMemory:
		return "ERROR_NOT_ENOUGH_MEMORY"
	case ErrorNotSupported:
		return "ERROR_NOT_SUPPORTED"
	case ErrorInvalidParameter:
		return "ERROR_INVALID_PARAMETER"
	case ErrorInvalidName:
		return "ERROR_INVALID_NAME"
	case ErrorInvalidLevel:
		return "ERROR_INVALID_LEVEL"
	case ErrorMoreData:
		return "ERROR_MORE_DATA"
	case ErrorInvalidDomainRole:
		return "ERROR_INVALID_DOMAIN_ROLE"
	case ErrorNoSuchDomain:
		return "ERROR_NO_SUCH_DOMAIN"
	case NerrBufTooSmall:
		return "NERR_BufTooSmall"
	case NerrWkstaNotStarted:
		return "NERR_WkstaNotStarted"
	case NerrUseNotFound:
		return "NERR_UseNotFound"
	case NerrInvalidComputer:
		return "NERR_InvalidComputer"
	case NerrSetupAlreadyJoined:
		return "NERR_SetupAlreadyJoined"
	case NerrSetupNotJoined:
		return "NERR_SetupNotJoined"
	case NerrSetupDomainController:
		return "NERR_SetupDomainController"
	case NerrDefaultJoinRequired:
		return "NERR_DefaultJoinRequired"
	default:
		return fmt.Sprintf("0x%08x", status)
	}
}

